INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96313,0,0,'If you don\'t have time to explain, then I don\'t have time to waste on you.',12,0,100.0,14,0,0,105840,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96313,1,0,'You\'re fortunate that Khadgar trusts you. But make no mistake... I do not share his sentiment.',12,0,100.0,1,0,0,105851,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96313,2,0,'You may enter the hold, but I will not put the lives of my guards at risk for your mission. Is that clear?',12,0,100.0,1,0,0,97848,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96313,3,0,'Lower the barrier and evacuate the hold. These Illidari wish to... exchange words... with the eredar.',12,0,100.0,1,0,0,97851,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96313,4,0,'Follow me. I shall open the cell for you.',12,0,100.0,25,0,0,97859,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96313,5,0,'Meet Taldath, one of the most powerful eredar we\'ve ever encountered. I\'m sure you two will be fast friends.',12,0,100.0,0,0,57564,97278,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96313,6,0,'Remember, demon hunter... you were never here.',12,0,100.0,1,0,0,97857,0,'LegionCore');
