INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,0,0,'I see you will not be deterred. Come then, Illidari. Face your destiny.',14,0,100.0,25,0,66891,113543,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,1,0,'Even here, I have heard your name spoken, $p. But, I am not impressed.',12,0,100.0,0,0,66892,113544,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,2,0,'Let us see if I can impress you.',12,0,100.0,0,0,66893,113545,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,3,0,'Shall we finish this like beings of honor? Can you manage that much, demon hunter?',12,0,100.0,0,0,66894,113546,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,4,0,'Open the skies!',14,0,100.0,0,0,68821,118783,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,5,0,'The storm clouds gather...',14,0,100.0,0,0,68817,118782,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,7,0,'You show some skill. But not as much as your dead master.',12,0,100.0,0,0,61929,113937,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,11,0,'Tell me, demon hunter, how did it feel being locked up for all of those years?',12,0,100.0,0,0,66889,113938,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,12,0,'|TInterface\\Icons\\shaman_pvp_lightninglasso:20|t%s is casting |cFFFF0000|Hspell:220101|h[Deathbolt]|h|r! Interrupt it!',41,0,100.0,0,0,0,118755,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,15,0,'This is impossible.',12,0,100.0,0,0,66890,113939,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108090,16,0,'Just kill me and be done with it.',12,0,100.0,0,0,66898,113556,0,'LegionCore');
