INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108250,3,0,'I know everything Akama knows, and more. I look forward to us working together to destroy the Legion.',12,0,100.0,1,0,66952,115848,0,'LegionCore');
